export function createElement(type, props, ...children) {
  return { type, props: props ?? {}, children, key: props?.key ?? null };
}

export function cloneElement(element, props, ...children) {
  return {
    ...element,
    props: { ...(element.props ?? {}), ...(props ?? {}) },
    children,
  };
}

export function forwardRef(render) {
  return render;
}

export function memo(component) {
  return component;
}

export function normalizeProps(props) {
  return props;
}

export function useComponentRef(ref) {
  return ref;
}

export default {
  createElement,
  cloneElement,
  forwardRef,
  memo,
  normalizeProps,
  useComponentRef,
};
